 void startLocation(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},41);return;}stopLocation();locationListener=new LocationListener(){@Override public void onLocationChanged(Location l){emit("mapintel-location",json("longitude",l.getLongitude(),"latitude",l.getLatitude(),"accuracy",l.getAccuracy(),"timestamp",l.getTime()));}@Override public void onProviderDisabled(String p){emit("mapintel-location",json("error","Location provider disabled. Enable the phone's Location setting."));}};boolean started=false;for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})try{if(locations.isProviderEnabled(provider)){locations.requestLocationUpdates(provider,5000,3,locationListener,Looper.getMainLooper());Location last=locations.getLastKnownLocation(provider);if(last!=null)locationListener.onLocationChanged(last);started=true;}}catch(SecurityException ignored){}if(!started)emit("mapintel-location",json("error","Enable Location on the phone to show your position."));}
